<template><view class="page"><view class="title">{{name}}的授权健康数据</view><view class="tabs"><text v-for="t in types" :key="t.value" :class="{active:type===t.value}" @tap="change(t.value)">{{t.label}}</text></view><view v-for="item in list" :key="item.id" class="card"><b>{{item.dataTypeText||item.dataType}}</b><view class="value">{{display(item)}}</view><text>{{item.measuredAt}}</text></view><view v-if="!list.length" class="empty">当前授权范围内暂无数据</view></view></template><script>import{getAuthorizedHealthData}from'@/api/health.js';export default{data(){return{ownerUserId:'',name:'用户',type:'',list:[],types:[{label:'全部',value:''},{label:'血糖',value:'GLUCOSE'},{label:'饮食',value:'DIET'},{label:'运动',value:'EXERCISE'},{label:'用药',value:'MEDICINE'}]}},onLoad(o){this.ownerUserId=o.ownerUserId;this.name=decodeURIComponent(o.name||'用户');this.load()},methods:{rows(r){const d=r&&r.data?r.data:r;return(d&&d.list)||d||[]},change(v){this.type=v;this.load()},load(){getAuthorizedHealthData(this.ownerUserId,{dataType:this.type,page:1,limit:100}).then(r=>this.list=this.rows(r)).catch(()=>this.list=[])},display(i){if(i.numericValue!=null)return i.numericValue+' '+(i.unit||'');try{const d=JSON.parse(i.detail||'{}');return d.content||d.category||'已记录'}catch(e){return'已记录'}}}}</script><style lang="scss" scoped>.page{min-height:100vh;background:#f6f7f8;padding:24rpx}.title{font-size:34rpx;font-weight:700;margin:22rpx 0}.tabs{display:flex;overflow:auto;background:#fff;border-radius:16rpx;padding:15rpx}.tabs text{padding:12rpx 22rpx;white-space:nowrap}.tabs .active{background:#19bf9b;color:#fff;border-radius:999rpx}.card{background:#fff;border-radius:18rpx;padding:24rpx;margin-top:16rpx}.value{font-size:34rpx;margin:16rpx 0}.card text{color:#999;font-size:23rpx}.empty{text-align:center;padding:100rpx;color:#aaa}</style>